import json
import logging
import boto3

from utils.get_config import get_device_config

logger = logging.getLogger()
logger.setLevel(logging.INFO)

client_mqtt = boto3.client('iot-data', region_name='us-east-1')

def send_device_configs_to_mqtt(
        config: dict,
        routine: dict,
        smartly_id:str,
        config_target:str
    ) -> dict:
    """
    Publish a pauload to devices's shadow topic using MQTT.
    """
    if config is not None or routine is not None:
        logger.info(f"bom dia ")
        if config_target == "config":
            config["envID"] = 0
            config["stage"] = ""

        config_payload = {
            "state": {
                "desired": {
                    "config": config,
                    "routine": routine
                }
            }
        }
        try:
            topic = f"$aws/things/{smartly_id}/shadow/name/{config_target}/update"
            logger.info(f'config_payload: {config_payload}')
            response_config = client_mqtt.publish(
                topic = topic,
                qos = 1,
                payload = json.dumps(config_payload)
            )
            logger.info(f"response_config: {response_config}")
        except Exception as e:
            logger.error(f"Erro ao publicar config: {e}")
            return {
                "error": 1,
                "body": f"Falha ao enviar {config_target}"
            }

    return {
        "status": 200,
        "response": "configuração enviada com sucesso."
    }

def publish_shadows_config(group: int, smartly_id: str) -> dict:
    """
    Publish configuration and scenario data to the device's shadow topics via MQTT.
    """

    device_configs = get_device_config(group)

    if device_configs is None:
        return {
            "error": 1,
            "body": "Grupo não encontrado"
        }

    logger.info(f"device_configs: {device_configs}")
    config = device_configs.get("config", None)
    routine = device_configs.get("routine", None)
    sensor_routine = device_configs.get("sensorRoutine", None)
    scenario_config = device_configs.get("scenarioConfig", None)

    response_from_config = send_device_configs_to_mqtt(config, routine, smartly_id, "config").get("status", 500)

    response_from_scenario_config = send_device_configs_to_mqtt(scenario_config, sensor_routine, smartly_id, "scenarioConfig").get("status", 500)

    if 500 in (response_from_config, response_from_scenario_config):
        return {
            "error": 1,
            "body": "MQTT publish failed"
        }
    print(f"response_from_config: {response_from_config}")
    print(f"response_from_scenario_config: {response_from_scenario_config}")
    return {
        "status": 200,
        "body": "Configuração enviad com sucesso."
    }

import logging
import boto3
from boto3.dynamodb.conditions import Key

logger = logging.getLogger()
logger.setLevel(logging.INFO)

dynamodb = boto3.resource('dynamodb')
table = dynamodb.Table('RedirectTopic')

def remove_from_dynamo(smartly_id: str, user_id: int) -> dict:
    """
    Remove an item from DynamoDB table based on smartly ID and user ID.
    """

    try:

        response_dynamo = table.delete_item(
            Key={
                'smartlyId': smartly_id,
                'userId': user_id
            }
        )

    except Exception as e:
        logger.info(e)
        return{
            "error": 1,
            "body": str(e)
        }

    logger.info(f"Dynamo: {response_dynamo}")

    return response_dynamo
